/* ── NO button runaway (corner cycle) ── */
let cornerIdx=0;
const corners=[[20,20],[null,20,20,null],[null,null,20,20],[20,null,null,20]];
function runAway(){const b=document.getElementById('no-btn');b.style.position='fixed';const m=12;const c=corners[cornerIdx%4];cornerIdx++;b.style.top=c[0]!=null?c[0]+'%':'auto';b.style.right=c[1]!=null?c[1]+'%':'auto';b.style.bottom=c[2]!=null?c[2]+'%':'auto';b.style.left=c[3]!=null?c[3]+'%':'auto'}

/* ── Balloon Game ── */
const MAX_POPS=10;
let score=0,gameRunning=false,spawnTimer;
const colors=['#f8b4c8','#fcd5c0','#f0d68a','#e895b3','#a8d8ea','#c3aed6','#ff9a9e','#96e6a1'];
const faces=['🎈','🎁','⭐','🎀','💖','🌸','🎉','✨'];
function startGame(){gameRunning=true;score=0;updScore();document.getElementById('game-area').style.display='';document.getElementById('score-bar').style.display='';document.getElementById('play-again').style.display='';document.getElementById('game-end').style.display='none';spawnTimer=setInterval(spawnGameBalloon,900)}
function updScore(){document.getElementById('score').textContent='Score: '+score+' / '+MAX_POPS}
function endGame(){clearInterval(spawnTimer);gameRunning=false;document.getElementById('game-area').innerHTML='';document.getElementById('game-area').style.display='none';document.getElementById('score-bar').style.display='none';document.getElementById('play-again').style.display='none';document.getElementById('final-score').textContent='Score: '+score+' / '+MAX_POPS;document.getElementById('game-end').style.display='flex';launchBalloons()}
function spawnGameBalloon(){if(!gameRunning)return;const area=document.getElementById('game-area');if(area.children.length>12)return;const b=document.createElement('div');b.className='game-balloon';const sz=Math.random()*20+40;b.style.width=sz+'px';b.style.height=sz*1.25+'px';b.style.background=colors[Math.floor(Math.random()*colors.length)];b.style.left=Math.random()*(area.offsetWidth-sz)+'px';b.style.top=Math.random()*(area.offsetHeight-sz)+'px';b.textContent=faces[Math.floor(Math.random()*faces.length)];b.addEventListener('pointerdown',e=>{e.preventDefault();if(!gameRunning)return;b.classList.add('pop');score++;updScore();setTimeout(()=>b.remove(),300);if(score>=MAX_POPS)endGame()});area.appendChild(b);setTimeout(()=>{if(b.parentNode&&!b.classList.contains('pop'))b.remove()},3000)}
function resetGame(){clearInterval(spawnTimer);document.getElementById('game-area').innerHTML='';startGame()}

